class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Deposited {amount} Tk")
        else:
            print("Invalid amount")

    def withdraw(self, amount):
        if amount > self.balance:
            print(f"Cannot withdraw {amount} Tk: insufficient balance")
        else:
            self.balance -= amount
            print(f"Withdrew {amount} Tk")

    def show_balance(self):
        print(f"{self.owner}'s balance: {self.balance} Tk")

acc = BankAccount("Nusrat", 1000)
acc.deposit(500)
acc.withdraw(2000)
acc.withdraw(300)
acc.show_balance()

class Student:
    def __init__(self, name, roll, marks):
        self.name = name
        self.roll = roll
        self.marks = marks

    def total(self):
        return sum(self.marks)

    def average(self):
        return self.total() / len(self.marks)

    def result(self):
        if min(self.marks) < 40:
            return "Fail"
        elif self.average() >= 80:
            return "A+"
        elif self.average() >= 60:
            return "A"
        else:
            return "B"

students = [
    Student("Rahim", 101, [78, 85, 62]),
    Student("Sumaiya", 102, [88, 76, 91]),
    Student("Karim", 103, [55, 35, 70]),
    Student("Tanvir", 104, [65, 72, 58]),
]

print("Roll  Name      Total  Average  Result")
for s in students:
    print(f"{s.roll}   {s.name:<8}  {s.total():>5}  {s.average():>7.2f}  {s.result()}")

topper = students[0]
for s in students:
    if s.average() > topper.average():
        topper = s
print("Topper:", topper.name)

