class Shape:                         # Class
    def area(self):
        return 0

class Square(Shape):                 # Inheritance
    def __init__(self, side):
        self.__side = side           # Encapsulation (private)

    def area(self):                  # Polymorphism (overriding)
        return self.__side ** 2

class Circle(Shape):
    def __init__(self, r):
        self.__r = r

    def area(self):
        return round(3.1416 * self.__r ** 2, 2)

for s in [Square(4), Circle(3)]:     # Objects
    print(type(s).__name__, s.area())  # Message passing

class Largest:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z

    def find(self):
        if self.x >= self.y and self.x >= self.z:
            return self.x
        elif self.y >= self.z:
            return self.y
        else:
            return self.z

x = float(input("First number : "))
y = float(input("Second number: "))
z = float(input("Third number : "))
